// What the goal comes to once every unit whose task ended is settled: each settlement appended under the goal's lock.
function settledView(ports, id) {
  const pending = resumeView(ports.goals.read(id), ports.taskSummaries?.() ?? []).pending;
  for (const line of pending) ports.goals.append(id, "unit", line);
  return resumeView(ports.goals.read(id), ports.taskSummaries?.() ?? []);
}

